shapes.MetersUpdateRequest = {
  t = "struct",
  name = "MetersUpdateRequest",
  members = {
    { name = "id", bind = "label", schema = S.string, required = true },
    { name = "external_id", schema = S.string, nullable = true },
    { name = "metadata", schema = S.ref("MetersUpdateRequestMetadataMap") },
    { name = "name", schema = S.string, nullable = true },
    { name = "unit", schema = S.ref("MeterUnit"), nullable = true },
    { name = "custom_label", schema = S.string, nullable = true },
    { name = "custom_multiplier", schema = S.number, nullable = true },
    { name = "filter", schema = S.ref("Filter"), nullable = true },
    { name = "aggregation", schema = S.ref("MetersUpdateRequestAggregation"), nullable = true },
    { name = "is_archived", schema = S.boolean, nullable = true },
  },
}
shapes.MetersUpdateRequestAggregation = {
  t = "union",
  arms = { S.ref("CountAggregation"), S.ref("PropertyAggregation"), S.ref("UniqueAggregation") },
}
shapes.MetersUpdateRequestMetadataMap = {
  t = "map",
  value = S.ref("MetersUpdateRequestMetadataValue"),
}
shapes.MetersUpdateRequestMetadataValue = {
  t = "union",
  arms = { S.string, S.number, S.number, S.boolean },
}
